-- =====================================================================
-- DeservEat - staging -> dw: SCD1 and static dimensions (issue #9)
--
-- Run after the staging tables were filled from data/processed/p_*.csv
-- (src/loading/load_warehouse.py does both, in one transaction).
--
--   dim_activity                            static seed: insert new codes, correct changed values
--   dim_recipe, dim_restaurant, dim_landmark SCD Type 1: upsert on source_id, overwrite changed attributes
--   dim_date                                generated by 01_ddl.sql (not loaded here)
--   dim_user                                SCD Type 2: dw.apply_user_version(), called by the generator (#22)
--
-- Rules
--   - A row is updated only when one of its attributes really changed (IS DISTINCT FROM),
--     so a second run with the same files inserts 0 rows and updates 0 rows.
--   - The surrogate key (*_key) of an existing row never changes: facts stay valid.
--   - A row that disappears from the source stays in dw (facts may reference it).
--   - A staging row that breaks a dw CHECK (e.g. kcal out of range) makes the whole load fail:
--     the processing scripts should have rejected it, so this is a pipeline bug, not data to hide.
--
-- Output: one row per dimension with the number of inserted and updated rows.
-- =====================================================================

WITH
activities AS (
    INSERT INTO dw.dim_activity (activity_key, activity_name, intensity, met_value, speed_kmh)
    SELECT activity_key, activity_name, intensity, met_value, speed_kmh
    FROM staging.activities
    ON CONFLICT (activity_key) DO UPDATE
        SET activity_name = EXCLUDED.activity_name,
            intensity     = EXCLUDED.intensity,
            met_value     = EXCLUDED.met_value,
            speed_kmh     = EXCLUDED.speed_kmh
        WHERE (dw.dim_activity.activity_name, dw.dim_activity.intensity, dw.dim_activity.met_value, dw.dim_activity.speed_kmh)
              IS DISTINCT FROM (EXCLUDED.activity_name, EXCLUDED.intensity, EXCLUDED.met_value, EXCLUDED.speed_kmh)
    RETURNING (xmax = 0) AS inserted
),
recipes AS (
    INSERT INTO dw.dim_recipe (source_id, title, total_kcal, kcal_per_serving, category, ingredients, recipe_url, servings)
    SELECT source_id, title, total_kcal, kcal_per_serving, category, ingredients, recipe_url, servings
    FROM staging.recipes
    ON CONFLICT (source_id) DO UPDATE
        SET title            = EXCLUDED.title,
            total_kcal       = EXCLUDED.total_kcal,
            kcal_per_serving = EXCLUDED.kcal_per_serving,
            category         = EXCLUDED.category,
            ingredients      = EXCLUDED.ingredients,
            recipe_url       = EXCLUDED.recipe_url,
            servings         = EXCLUDED.servings
        WHERE (dw.dim_recipe.title, dw.dim_recipe.total_kcal, dw.dim_recipe.kcal_per_serving, dw.dim_recipe.category,
               dw.dim_recipe.ingredients, dw.dim_recipe.recipe_url, dw.dim_recipe.servings)
              IS DISTINCT FROM (EXCLUDED.title, EXCLUDED.total_kcal, EXCLUDED.kcal_per_serving, EXCLUDED.category,
                                EXCLUDED.ingredients, EXCLUDED.recipe_url, EXCLUDED.servings)
    RETURNING (xmax = 0) AS inserted
),
restaurants AS (
    INSERT INTO dw.dim_restaurant (source_id, restaurant_name, food_type, lat, lng, geom, overall_rating, district)
    SELECT source_id, restaurant_name, food_type, lat, lng,
           ST_SetSRID(ST_MakePoint(lng, lat), 4326)::GEOGRAPHY,
           overall_rating, district
    FROM staging.restaurants
    ON CONFLICT (source_id) DO UPDATE
        SET restaurant_name = EXCLUDED.restaurant_name,
            food_type       = EXCLUDED.food_type,
            lat             = EXCLUDED.lat,
            lng             = EXCLUDED.lng,
            geom            = EXCLUDED.geom,
            overall_rating  = EXCLUDED.overall_rating,
            district        = EXCLUDED.district
        WHERE (dw.dim_restaurant.restaurant_name, dw.dim_restaurant.food_type, dw.dim_restaurant.lat, dw.dim_restaurant.lng,
               dw.dim_restaurant.overall_rating, dw.dim_restaurant.district)
              IS DISTINCT FROM (EXCLUDED.restaurant_name, EXCLUDED.food_type, EXCLUDED.lat, EXCLUDED.lng,
                                EXCLUDED.overall_rating, EXCLUDED.district)
    RETURNING (xmax = 0) AS inserted
),
landmarks AS (
    INSERT INTO dw.dim_landmark (source_id, building_name, address, commune, insee_code, lat, lon, geom)
    SELECT source_id, building_name, address, commune, insee_code, lat, lon,
           ST_SetSRID(ST_MakePoint(lon, lat), 4326)::GEOGRAPHY
    FROM staging.landmarks
    ON CONFLICT (source_id) DO UPDATE
        SET building_name = EXCLUDED.building_name,
            address       = EXCLUDED.address,
            commune       = EXCLUDED.commune,
            insee_code    = EXCLUDED.insee_code,
            lat           = EXCLUDED.lat,
            lon           = EXCLUDED.lon,
            geom          = EXCLUDED.geom
        WHERE (dw.dim_landmark.building_name, dw.dim_landmark.address, dw.dim_landmark.commune, dw.dim_landmark.insee_code,
               dw.dim_landmark.lat, dw.dim_landmark.lon)
              IS DISTINCT FROM (EXCLUDED.building_name, EXCLUDED.address, EXCLUDED.commune, EXCLUDED.insee_code,
                                EXCLUDED.lat, EXCLUDED.lon)
    RETURNING (xmax = 0) AS inserted
)
SELECT 'dim_activity' AS dimension, count(*) FILTER (WHERE inserted) AS inserted, count(*) FILTER (WHERE NOT inserted) AS updated FROM activities
UNION ALL
SELECT 'dim_recipe',     count(*) FILTER (WHERE inserted), count(*) FILTER (WHERE NOT inserted) FROM recipes
UNION ALL
SELECT 'dim_restaurant', count(*) FILTER (WHERE inserted), count(*) FILTER (WHERE NOT inserted) FROM restaurants
UNION ALL
SELECT 'dim_landmark',   count(*) FILTER (WHERE inserted), count(*) FILTER (WHERE NOT inserted) FROM landmarks;
